sys_script_include.script:
var EmbeddingService = Class.create();
EmbeddingService.prototype = {
    initialize: function() {
        this.apiKey = gs.getProperty('x_2311790_skills_0.gemini_api_key');
        this.model = gs.getProperty('x_2311790_skills_0.embedding_model') || 'text-embedding-004';
        this.version = 'embedding-v1';
        this.dim = parseInt(gs.getProperty('x_2311790_skills_0.embedding_dim') || '768', 10);
        if (isNaN(this.dim) || this.dim <= 0)
            this.dim = 768;

        this.endpoint = gs.getProperty('x_2311790_skills_0.embedding_endpoint') ||
            ('https://generativelanguage.googleapis.com/v1beta/models/' + this.model + ':embedContent');
        this.maxAttempts = 3;
    },

    prepareProfile: function(profile) {
        try {
            if (!profile || !profile.getUniqueValue())
                return this._fail('INVALID_PROFILE', false, 'Missing profile record.', 0);

            var text = this._profileText(profile);
            if (!text)
                return this._fail('EMPTY_PROFILE_TEXT', false, 'Profile has no text to embed.', 0);

            var result = this.embedText(text);
            if (!result.ok)
                return result;

            result.embeddedAttachmentSysId = profile.getValue('u_parsed_attachment_sys_id') || '';
            return result;
        } catch (ex) {
            return this._fail('EXCEPTION', false, 'EmbeddingService profile exception: ' + (ex.message || ex), 0);
        }
    },

    prepareInternship: function(internship) {
        try {
            if (!internship || !internship.getUniqueValue())
                return this._fail('INVALID_INTERNSHIP', false, 'Missing internship record.', 0);

            var text = this._internshipText(internship);
            if (!text)
                return this._fail('EMPTY_INTERNSHIP_TEXT', false, 'Internship has no text to embed.', 0);

            return this.embedText(text);
        } catch (ex) {
            return this._fail('EXCEPTION', false, 'EmbeddingService internship exception: ' + (ex.message || ex), 0);
        }
    },

    embedText: function(text) {
        try {
            if (!this.apiKey)
                return this._fail('MISSING_API_KEY', false, 'Gemini API key is not configured.', 0);

            var source = String(text || '').replace(/^\s+|\s+$/g, '');
            if (!source)
                return this._fail('EMPTY_INPUT', false, 'Embedding input is empty.', 0);

            source = this._truncate(source, 12000);
            var payload = {
                model: 'models/' + this.model,
                content: {
                    parts: [{ text: source }]
                },
                taskType: 'SEMANTIC_SIMILARITY',
                outputDimensionality: this.dim
            };

            var response = this._callWithRetry(payload);
            if (!response.ok)
                return response;

            return this._parseEmbeddingResponse(response.body, response.attempts);
        } catch (ex) {
            return this._fail('EXCEPTION', false, 'EmbeddingService exception: ' + (ex.message || ex), 0);
        }
    },

    cosine: function(vectorA, vectorB) {
        var a = this._parseVector(vectorA);
        var b = this._parseVector(vectorB);
        if (!a.length || a.length !== b.length)
            return 0;

        var dot = 0;
        var normA = 0;
        var normB = 0;
        for (var i = 0; i < a.length; i++) {
            dot += a[i] * b[i];
            normA += a[i] * a[i];
            normB += b[i] * b[i];
        }
        if (!normA || !normB)
            return 0;

        var similarity = dot / (Math.sqrt(normA) * Math.sqrt(normB));
        if (similarity < 0)
            similarity = 0;
        if (similarity > 1)
            similarity = 1;
        return Math.round(similarity * 10000) / 10000;
    },

    _profileText: function(profile) {
        var parts = [];
        parts.push('Headline: ' + (profile.getValue('u_headline') || ''));
        parts.push('Summary: ' + (profile.getValue('u_parsed_resume') || ''));
        parts.push('Education: ' + (profile.getValue('u_education') || ''));
        parts.push('Projects: ' + (profile.getValue('u_projects') || ''));
        parts.push('Experience years: ' + (profile.getValue('u_experience_years') || '0'));

        var names = [];
        var skillGr = new GlideRecord('x_2311790_skills_0_student_skill');
        skillGr.addQuery('u_profile', profile.getUniqueValue());
        skillGr.orderBy('u_rank');
        skillGr.query();

        while (skillGr.next()) {
            var master = new GlideRecord('x_2311790_skills_0_skill_master');
            if (master.get(skillGr.getValue('u_skill'))) {
                var label = master.getValue('name') || '';
                if (skillGr.getValue('u_core') == 'true' || skillGr.getValue('u_core') == '1')
                    label += ' (core)';
                if (label)
                    names.push(label);
            }
        }

        parts.push('Skills and tools: ' + names.join(', '));
        return this._truncate(parts.join('\n'), 12000);
    },

    _internshipText: function(internship) {
        var parts = [];
        parts.push('Title: ' + (internship.getValue('short_description') || internship.getDisplayValue('')));
        parts.push('Requirements: ' + (internship.getValue('u_requirements') || ''));
        parts.push('Required skills: ' + this._readSkillList(internship.getValue('u_required_skills')).join(', '));
        parts.push('Preferred skills: ' + this._readSkillList(internship.getValue('u_preferred_skills')).join(', '));
        parts.push('Minimum experience years: ' + (internship.getValue('u_min_experience_years') || '0'));
        return this._truncate(parts.join('\n'), 12000);
    },

    _readSkillList: function(raw) {
        var text = String(raw || '');
        if (!text)
            return [];

        try {
            var parsed = JSON.parse(text);
            if (Object.prototype.toString.call(parsed) === '[object Array]') {
                var values = [];
                for (var i = 0; i < parsed.length; i++) {
                    var item = parsed[i];
                    var name = typeof item === 'string' ? item : (item && item.name) || '';
                    name = String(name).replace(/^\s+|\s+$/g, '');
                    if (name)
                        values.push(name);
                }
                return values;
            }
        } catch (e) {}

        var chunks = text.split(/[\n,;]+/);
        var result = [];
        for (var j = 0; j < chunks.length; j++) {
            var value = chunks[j].replace(/^\s+|\s+$/g, '');
            if (value)
                result.push(value);
        }
        return result;
    },

    _callWithRetry: function(payload) {
        var bodyText = JSON.stringify(payload);
        var lastStatus = 0;

        for (var attempt = 1; attempt <= this.maxAttempts; attempt++) {
            try {
                var r = new sn_ws.RESTMessageV2();
                r.setEndpoint(this.endpoint);
                r.setHttpMethod('POST');
                r.setRequestHeader('Content-Type', 'application/json');
                r.setRequestHeader('x-goog-api-key', this.apiKey);
                r.setRequestBody(bodyText);

                var response = r.execute();
                lastStatus = response.getStatusCode();
                var body = response.getBody() || '';
                if (lastStatus == 200)
                    return { ok: true, body: body, attempts: attempt };

                var retryable = this._isRetryable(lastStatus);
                if (!retryable || attempt === this.maxAttempts)
                    return this._fail('HTTP_' + lastStatus, retryable, 'Embedding HTTP ' + lastStatus + ': ' + this._truncate(body, 500), attempt);

                this._sleep(this._backoffMs(attempt));
            } catch (ex) {
                if (attempt === this.maxAttempts)
                    return this._fail('HTTP_EXCEPTION', true, 'Embedding request exception: ' + (ex.message || ex), attempt);
                this._sleep(this._backoffMs(attempt));
            }
        }

        return this._fail('RETRY_EXHAUSTED', true, 'Embedding retries exhausted. Last status: ' + lastStatus, this.maxAttempts);
    },

    _parseEmbeddingResponse: function(body, attempts) {
        try {
            var outer = JSON.parse(body);
            if (outer.error)
                return this._fail('API_ERROR', false, this._truncate(outer.error.message || 'Embedding API error.', 500), attempts);

            var values = outer.embedding && outer.embedding.values;
            if (!this._isArray(values) || values.length === 0)
                return this._fail('EMPTY_EMBEDDING', false, 'Embedding response contained no values.', attempts);

            if (values.length !== this.dim)
                return this._fail('DIMENSION_MISMATCH', false, 'Expected ' + this.dim + ' dimensions but got ' + values.length + '.', attempts);

            var vector = this._vectorToString(values);
            if (vector.length > 8000)
                return this._fail('EMBEDDING_TOO_LARGE', false, 'Compact embedding exceeds 8000 characters.', attempts);

            return {
                ok: true,
                vector: vector,
                dim: this.dim,
                model: this.model,
                version: this.version,
                attempts: attempts
            };
        } catch (ex) {
            return this._fail('INVALID_RESPONSE', false, 'Could not parse embedding response: ' + (ex.message || ex), attempts);
        }
    },

    _vectorToString: function(values) {
        var parts = [];
        for (var i = 0; i < values.length; i++) {
            var value = parseFloat(values[i]);
            if (isNaN(value))
                value = 0;
            parts.push(Math.round(value * 10000) / 10000);
        }
        return parts.join(',');
    },

    _parseVector: function(vector) {
        if (!vector || typeof vector !== 'string')
            return [];
        var chunks = vector.split(',');
        var values = [];
        for (var i = 0; i < chunks.length; i++) {
            var value = parseFloat(chunks[i]);
            if (!isNaN(value))
                values.push(value);
        }
        return values;
    },

    _isRetryable: function(status) {
        return status == 0 || status == 429 || status >= 500;
    },

    _backoffMs: function(attempt) {
        return attempt === 1 ? 1000 : 2000;
    },

    _sleep: function(ms) {
        try {
            if (typeof gs.sleep === 'function') {
                gs.sleep(ms);
                return;
            }
        } catch (e) {}

        try {
            Packages.java.lang.Thread.sleep(ms);
        } catch (e2) {}
    },

    _isArray: function(value) {
        return Object.prototype.toString.call(value) === '[object Array]';
    },

    _truncate: function(value, maxLength) {
        var text = String(value || '');
        if (text.length > maxLength)
            return text.substring(0, maxLength - 3) + '...';
        return text;
    },

    _fail: function(code, retryable, message, attempts) {
        return {
            ok: false,
            errorCode: code,
            retryable: !!retryable,
            errorMessage: message,
            attempts: attempts || 0
        };
    },

    type: 'EmbeddingService'
};
